import products from './products.json' with {type:'json'};

export async function listTools() {
  return [{
    name: 'inventory_search',
    description: 'Search products by name',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search query to match against product names' },
        limit: { type: 'integer', description: 'Maximum number of results (1-10)', minimum: 1, maximum: 10 }
      },
      required: ['query']
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error('Unknown tool: ' + name);
  }

  if (!args || typeof args.query !== 'string') {
    throw new Error('Invalid arguments: query is required and must be a string');
  }

  let limit = 10; // default
  if (args.limit !== undefined) {
    limit = args.limit;
    if (!Number.isInteger(limit) || limit < 1 || limit > 10) {
      throw new Error('Invalid arguments: limit must be an integer between 1 and 10');
    }
  }

  const query = args.query.toLowerCase();
  const results = products
    .filter(p => p.name.toLowerCase().includes(query))
    .slice(0, limit);

  return {
    content: [{
      type: 'text',
      text: JSON.stringify(results)
    }]
  };
}
```

